-- Clause Check sample data for the SQL and BigQuery days (generated by a script; do not edit by hand).
-- Six customers, ten contracts, one row per clause review, eval runs and tool calls.
CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  country TEXT NOT NULL,          -- ISO code: SE, NO, EE, US, FI, NL
  plan TEXT NOT NULL,             -- starter / pro / enterprise
  signed_up TEXT NOT NULL         -- date, YYYY-MM-DD
);
CREATE TABLE contracts (
  id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(id),
  title TEXT NOT NULL,
  uploaded_at TEXT NOT NULL,      -- timestamp, YYYY-MM-DD HH:MM:SS (UTC)
  pages INTEGER NOT NULL,
  status TEXT NOT NULL            -- reviewed / in_review / failed
);
CREATE TABLE reviews (
  id INTEGER PRIMARY KEY,
  contract_id INTEGER NOT NULL REFERENCES contracts(id),
  clause_id TEXT NOT NULL,        -- '8.1', '10.1' ... (text, so '10.1' < '8.1' when sorted as text)
  heading TEXT NOT NULL,
  topic TEXT NOT NULL,
  verdict TEXT,                   -- accept / flag / redline; NULL when the review failed
  risk TEXT,                      -- low / medium / high; NULL when the review failed
  rule_ids TEXT,                  -- JSON array as text, e.g. '["PB-01", "PB-02"]'
  model TEXT NOT NULL,            -- deepseek-v4-flash / deepseek-v4-pro
  prompt_version TEXT NOT NULL,   -- v1 / v2
  prompt_tokens INTEGER NOT NULL,
  completion_tokens INTEGER NOT NULL,
  cache_hit_tokens INTEGER NOT NULL,
  latency_ms INTEGER NOT NULL,
  cost_usd REAL NOT NULL,         -- at the peak list price per model (2026-09)
  error TEXT,                     -- NULL unless the review failed
  created_at TEXT NOT NULL        -- timestamp, YYYY-MM-DD HH:MM:SS (UTC)
);
CREATE TABLE evals (
  id INTEGER PRIMARY KEY,
  case_id TEXT NOT NULL,
  prompt_version TEXT NOT NULL,
  run INTEGER NOT NULL,           -- 1..3
  expected TEXT NOT NULL,         -- the verdict the case expects
  verdict TEXT NOT NULL,          -- what the model answered
  passed INTEGER NOT NULL,        -- 1 / 0
  latency_ms INTEGER NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE tool_calls (
  id INTEGER PRIMARY KEY,
  review_id INTEGER NOT NULL REFERENCES reviews(id),
  step INTEGER NOT NULL,
  tool TEXT NOT NULL,             -- lookup_playbook / get_clause / mark_for_review
  args TEXT NOT NULL,             -- JSON object as text
  ok INTEGER NOT NULL,            -- 1 / 0
  latency_ms INTEGER NOT NULL
);
